"""Shared helpers for executable examples."""

from __future__ import annotations

from pathlib import Path

from macro_viz import Config

OUTPUT_DIR = Path(__file__).resolve().parent.parent / "output"


def prepare_manual_output() -> Path:
    """Use the black-and-white manual theme and return the output directory."""
    Config.from_dict({"base": "manual"}).use()
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    return OUTPUT_DIR


def clear_images() -> None:
    """Remove images generated by an earlier example run."""
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    for image in OUTPUT_DIR.glob("*.png"):
        image.unlink()
